CREATE OR REPLACE FUNCTION public.review_learning_mistake(p_question text,p_answer integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q jsonb; mastered boolean; p text; BEGIN SELECT parcours INTO p FROM public.profiles WHERE id=auth.uid(); IF p IS NULL THEN RAISE EXCEPTION 'Connectez-vous pour réviser.'; END IF; SELECT v INTO q FROM public.learning_sessions s CROSS JOIN LATERAL jsonb_array_elements(s.questions) WITH ORDINALITY a(v,n) WHERE s.user_id=auth.uid() AND s.parcours=p AND s.completed_at IS NOT NULL AND v->>'id'=p_question AND (s.answers->>((n-1)::text))::integer IS DISTINCT FROM (v->>'answer')::integer ORDER BY s.started_at DESC LIMIT 1; IF q IS NULL THEN RAISE EXCEPTION 'Erreur introuvable.'; END IF; IF p_answer<0 OR p_answer>=jsonb_array_length(q->'options') THEN RAISE EXCEPTION 'Réponse invalide.'; END IF; mastered:=p_answer=(q->>'answer')::integer; INSERT INTO public.learning_sessions(user_id,parcours,kind,questions,answers,total,correct,completed_at) VALUES(auth.uid(),p,'review',jsonb_build_array(q),jsonb_build_object('0',p_answer),1,CASE WHEN mastered THEN 1 ELSE 0 END,now()); INSERT INTO public.learning_mistake_reviews(user_id,question_id,mastered) VALUES(auth.uid(),p_question,mastered) ON CONFLICT(user_id,question_id) DO UPDATE SET mastered=excluded.mastered,updated_at=now(); RETURN mastered; END $$;